<?= $this->extend('layouts/admin') ?><?= $this->section('content') ?><section class="admin-title"><p>CMS overview</p><h1>Good day, <?= esc($adminName) ?>.</h1><span>Manage the content and customer requests that power Fynefield's website.</span></section><div class="metrics"><?php foreach ($counts as $key => $count): ?><a href="<?= site_url('admin/' . $key) ?>"><strong><?= $count ?></strong><span><?= esc($entities[$key]['label']) ?></span></a><?php endforeach ?></div><section class="quick"><h2>Start with a task</h2><div><a href="<?= site_url('admin/posts/new') ?>">Write a news update</a><a href="<?= site_url('admin/services/new') ?>">Add a service</a><a href="<?= site_url('admin/media') ?>">Upload an image</a></div></section><section class="activity-feed"><h2>Recent editorial activity</h2><?php foreach ($recentActivity as $activity): ?><p><strong><?= esc($activity['user_name'] ?: 'System') ?></strong> <?= esc($activity['action']) ?><?= $activity['entity_type'] ? ' · ' . esc($activity['entity_type']) : '' ?> <small><?= esc($activity['created_at']) ?></small></p><?php endforeach ?><?php if (! $recentActivity): ?><p>No editorial activity yet.</p><?php endif ?></section><?= $this->endSection() ?>
